arguments.command:
python3 -c '
import sqlite3, hashlib, json, os, sys

WORKDIR = "/tmp/llm-super-agent/phoenix-ledger"
discrepancies = []

def disc(msg):
    discrepancies.append(msg)
    sys.stderr.write(f"DISC: {msg}\n")

# --- Load untrusted claims ---
with open(f"{WORKDIR}/manifest.json") as f:
    manifest = json.load(f)
with open(f"{WORKDIR}/acceptance.json") as f:
    acceptance = json.load(f)
with open(f"{WORKDIR}/fixture-baseline.json") as f:
    fixture = json.load(f)
with open(f"{WORKDIR}/backup/backup-manifest.json") as f:
    backup_manifest = json.load(f)
with open(f"{WORKDIR}/backup/restore-check.json") as f:
    restore_check = json.load(f)

# --- Observed file hashes ---
backup_real_sha = hashlib.sha256(open(f"{WORKDIR}/backup/ledger-pre-v2.db","rb").read()).hexdigest()
restore_real_sha = hashlib.sha256(open(f"{WORKDIR}/backup/restore-rehearsal.db","rb").read()).hexdigest()

