import json, sys

# Parse traffic.log strictly
seqs = set()
errors = []
with open('/tmp/llm-super-agent/phoenix-ledger/traffic.log', 'r') as f:
    for line_num, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            errors.append(f'line {line_num}: invalid JSON')
            continue
        seq = rec.get('seq')
        status = rec.get('status')
        acknowledged = rec.get('acknowledged')
        if not isinstance(seq, int) or not isinstance(status, int) or not isinstance(acknowledged, bool):
            errors.append(f'line {line_num}: type error seq={type(seq).__name__} status={type(status).__name__} ack={type(acknowledged).__name__}')
            continue
        if status < 200 or status >= 300:
            errors.append(f'line {line_num}: non-2xx status={status}')
        if not acknowledged:
            errors.append(f'line {line_num}: acknowledged is false')
        if seq in seqs:
            errors.append(f'line {line_num}: duplicate seq={seq}')
        seqs.add(seq)

if not seqs:
    errors.append('no records parsed')

seq_list = sorted(seqs)
for i, s in enumerate(seq_list):
    if s != i + 1:
        errors.append(f'seq discontinuity: expected {i+1}, got {s}')
        break

if errors:
    print('FAIL:')
    for e in errors:
        print(f'  {e}')
    sys.exit(1)
else:
    print(f'OK: {len(seqs)} records, contiguous 1..{len(seqs)}, all 2xx, all acknowledged')
    sys.exit(0)
